CREATE DATABASE IF NOT EXISTS ift_result_tracking CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ift_result_tracking;
DROP TABLE IF EXISTS email_logs, activity_logs, result_movements, result_records, course_lecturers, courses, lecturers, offices, status_stages, users, settings;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(120) NOT NULL, username VARCHAR(80) NOT NULL UNIQUE, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','hod') NOT NULL DEFAULT 'admin', is_active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE lecturers (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(150) NOT NULL, phone VARCHAR(30) NULL, is_active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE offices (id INT AUTO_INCREMENT PRIMARY KEY, office_name VARCHAR(120) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE status_stages (id INT AUTO_INCREMENT PRIMARY KEY, stage_order INT NOT NULL UNIQUE, stage_name VARCHAR(120) NOT NULL UNIQUE, office_id INT NULL, delay_days INT NOT NULL DEFAULT 3, FOREIGN KEY (office_id) REFERENCES offices(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE courses (id INT AUTO_INCREMENT PRIMARY KEY, course_code VARCHAR(20) NOT NULL UNIQUE, course_title VARCHAR(180) NOT NULL, level INT NOT NULL, semester ENUM('First Semester','Second Semester') NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, CHECK(level IN (100,200,300,400))) ENGINE=InnoDB;
CREATE TABLE course_lecturers (course_id INT NOT NULL, PRIMARY KEY(course_id,lecturer_id), FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE result_records (id INT AUTO_INCREMENT PRIMARY KEY, tracking_no VARCHAR(30) NOT NULL UNIQUE, public_token CHAR(32) NOT NULL UNIQUE, course_id INT NOT NULL, session_name VARCHAR(20) NOT NULL, number_of_scripts INT NOT NULL DEFAULT 0, current_stage_id INT NOT NULL, current_office_id INT NULL, current_since DATETIME NOT NULL, received_at DATETIME NOT NULL, created_by INT NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(course_id) REFERENCES courses(id), FOREIGN KEY(current_stage_id) REFERENCES status_stages(id), FOREIGN KEY(current_office_id) REFERENCES offices(id) ON DELETE SET NULL, FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE result_movements (id BIGINT AUTO_INCREMENT PRIMARY KEY, result_id INT NOT NULL, from_stage_id INT NULL, to_stage_id INT NOT NULL, from_office_id INT NULL, to_office_id INT NULL, handed_over_by VARCHAR(120) NOT NULL, received_by VARCHAR(120) NULL, remarks TEXT NULL, moved_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, user_id INT NULL, FOREIGN KEY(result_id) REFERENCES result_records(id) ON DELETE CASCADE, FOREIGN KEY(from_stage_id) REFERENCES status_stages(id) ON DELETE SET NULL, FOREIGN KEY(to_stage_id) REFERENCES status_stages(id), FOREIGN KEY(from_office_id) REFERENCES offices(id) ON DELETE SET NULL, FOREIGN KEY(to_office_id) REFERENCES offices(id) ON DELETE SET NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE activity_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, result_id INT NULL, user_id INT NULL, action VARCHAR(180) NOT NULL, received_by VARCHAR(120) NULL, note TEXT NULL, ip_address VARCHAR(45) NULL, user_agent VARCHAR(255) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(result_id) REFERENCES result_records(id) ON DELETE SET NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE email_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, result_id INT NULL, recipient VARCHAR(180) NOT NULL, event_name VARCHAR(120) NOT NULL, subject VARCHAR(255) NOT NULL, status ENUM('Sent','Failed') NOT NULL, error_message TEXT NULL, sent_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(result_id) REFERENCES result_records(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE settings (id INT AUTO_INCREMENT PRIMARY KEY, setting_key VARCHAR(100) NOT NULL UNIQUE, setting_value VARCHAR(255) NOT NULL) ENGINE=InnoDB;
